 const keep=(key,item)=>{if(!item)throw new Error('Choose a template first.');if(api.library){api.library.attach(project(),key,item);return;}project()[key]??=[];if(!project()[key].some(v=>v.id===item.id))project()[key].push(structuredClone(item));};
 const uid=()=>globalThis.crypto?.randomUUID?.()||'smart-'+Date.now()+'-'+Math.random().toString(36).slice(2);
 const imgHTML=(tile,w=128,h=96)=>{const a=api.asset(tile.a||tile.assetId);if(!a)return'';const sw=tile.sw||w,sh=tile.sh||h;return`<svg class="smart-thumb" viewBox="${tile.sx||0} ${tile.sy||0} ${sw} ${sh}" role="img" aria-label="${esc(tile.name||a.name)}"><image href="${esc(a.data||a.src)}" x="0" y="0" width="${a.width}" height="${a.height}"/></svg>`;};
